// Recommandation d'index selon lecture/écriture, sélectivité, type de requête.
export function indexAdvice({ reads, writes, selectiveColumn, rangeQueries }) {
  // BUG : recommande toujours un index dès qu'il y a des lectures.
  return reads > 0 ? 'btree-index' : 'no-index';
}

